head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[linkedDataList > M > getRangeData]<br/>Row 의 인덱스값을 사용하여 특정 범위의 Row 데이터를 1차원 배열로 반환합니다.",
    "validation" : [
        "from(필수) 파라미터로 반환 받으려는 Row 데이터의 시작 인덱스값을 숫자로 설정합니다.",
        "to(필수) 파라미터로 반환 받으려는 Row 데이터의 마지막 인덱스값을 숫자로 설정합니다.",
        "Row 의 인덱스는 0 부터 시작하며 LinkedDataList 모듈의 필터링/정렬 설정에 맞게 인덱스를 설정합니다.",
        "반환값으로 필터/정렬이 적용된 상태를 기준으로 파라미터 범위의 Row 데이터를 1차원 배열로 반환합니다.",
        "setColumnFilter() 메소드로 필터링 되지 않은 경우 전체 Row 데이터를 기준으로 동작합니다.",
        "배열은 LinkedDataList 모듈에 정렬이 적용된 순서대로 생성됩니다.",
        "Row 상태값에 관계없이 파라미터 범위에 만족하는 Row 데이터를 반환합니다.",
        "from, to 파라미터값이 Row 의 인덱스값이 아니어도 범위가 유효하다면 getRangeData() 메소드는 동작합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
	// 기존 target 있으면 삭제
    if (typeof gdl_org !== 'undefined') {
        $p.data.remove("gdl_org");
    }

    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }   

    if (typeof gridView2 !== 'undefined') {
        gridView2.remove();
    }   

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

	// target 생성
    $c.gcm.createOrginalDataList();
    $c.gcm.createBasicLinkedDataList();

    // gridView 생성
    $c.gcm.createOriginalGridView();
    $c.gcm.createLinkedGridView();

    // 상태 변경
    scwin.btn_insertRow_onclick();
    scwin.btn_deleteRow_onclick();
    scwin.btn_setCellData_onclick();
    scwin.btn_removeRow_onclick();
}   



scwin.btn_insertRow_onclick = function (e) {
    let insertIndex = gdl_org.insertRow();
    gdl_org.setRowData(insertIndex,["A","insert2","insert3","insert4"],true);

    gdl_org.deleteRow(insertIndex);
};



scwin.btn_deleteRow_onclick = function (e) {
    gdl_org.deleteRow(0);
};



scwin.btn_setCellData_onclick = function (e) {
    gdl_org.setCellData(2, "cat2", "change");
};



scwin.btn_removeRow_onclick = function (e) {
    gdl_org.removeRow(3);
}



scwin.btn_setColumnFilter_onclick = function (e) {
	target1.setColumnFilter({type:"row", colIndex:"cat2", key:"A1", condition:"and"});
};



scwin.btn_sort_onclick = function (e) {
    target1.sort("label", 1);
};



scwin.btn_getRangeData_onclick = function (e) {
    let rtn = '';
    let nFrom = par_from.getText();
    let nTo = par_to.getText();

    rtn = target1.getRangeData(Number(nFrom), Number(nTo));

    wf_body_bottom.getObj("scwin").setReturnValue("result: " + rtn);
};
